From 72db0a00e09d2100d8c20c7a3964bad4b8154137 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:51:19 +0100
Subject: [PATCH] applets/kicker: fade out the Application Dashboard when
 closing it

The dashboard disappeared in a single frame when it was closed, which
felt abrupt next to the rest of Plasma. Now its contents fade out over
the standard animation duration before the window is hidden.

BUG: 454717
---
 applets/kicker/CompactRepresentation.qml   |  8 +++---
 applets/kicker/DashboardRepresentation.qml | 32 ++++++++++++++++++++++
 applets/kicker/main.qml                    |  2 +-
 3 files changed, 37 insertions(+), 5 deletions(-)

diff --git a/applets/kicker/CompactRepresentation.qml b/applets/kicker/CompactRepresentation.qml
index 896b9deafb..cbda2ff98f 100644
--- a/applets/kicker/CompactRepresentation.qml
+++ b/applets/kicker/CompactRepresentation.qml
@@ -38,8 +38,8 @@ MouseArea {

     property string toolTipSubText: ""
     property Component dashWindowComponent
-    readonly property Kicker.DashboardWindow dashWindow: isDash && dashWindowComponent && dashWindowComponent.status === Component.Ready
-        ? dashWindowComponent.createObject(root, { visualParent: root }) as Kicker.DashboardWindow : null
+    readonly property DashboardRepresentation dashWindow: isDash && dashWindowComponent && dashWindowComponent.status === Component.Ready
+        ? dashWindowComponent.createObject(root, { visualParent: root }) as DashboardRepresentation : null

     // Taken from DigitalClock to ensure uniform sizing when next to each other
     readonly property bool tooSmall: Plasmoid.formFactor === PlasmaCore.Types.Horizontal && Math.round(2 * (root.height / 5)) <= Kirigami.Theme.smallFont.pixelSize
@@ -108,7 +108,7 @@ MouseArea {

     onClicked: mouse => {
         if (isDash) {
-            dashWindow.toggle();
+            dashWindow.toggleAnimated();
         } else {
             expandRequested(!wasExpanded);
         }
@@ -124,7 +124,7 @@ MouseArea {
         enabled: root.isDash && root.dashWindow !== null

         function onActivated(): void {
-            root.dashWindow.toggle();
+            root.dashWindow.toggleAnimated();
         }
     }

diff --git a/applets/kicker/DashboardRepresentation.qml b/applets/kicker/DashboardRepresentation.qml
index b0a6c9500c..b0cbff6840 100644
--- a/applets/kicker/DashboardRepresentation.qml
+++ b/applets/kicker/DashboardRepresentation.qml
@@ -74,6 +74,23 @@ Kicker.DashboardWindow {
         }
     }

+    function hideAnimated(): void {
+        if (!fadeOutAnimation.running) {
+            fadeOutAnimation.start();
+        }
+    }
+
+    function toggleAnimated(): void {
+        if (fadeOutAnimation.running) {
+            fadeOutAnimation.stop();
+            rootItem.opacity = 1;
+        } else if (visible) {
+            hideAnimated();
+        } else {
+            toggle();
+        }
+    }
+
     function reset() {
         searchField.clear();
         searchField.forceActiveFocus(Qt.OtherFocusReason)
@@ -114,6 +131,21 @@ Kicker.DashboardWindow {
             opacity: 0.737
         }

+        NumberAnimation {
+            id: fadeOutAnimation
+
+            target: rootItem
+            property: "opacity"
+            to: 0
+            duration: Kirigami.Units.longDuration
+            easing.type: Easing.InOutQuad
+
+            onFinished: {
+                root.close();
+                rootItem.opacity = 1;
+            }
+        }
+
         Connections {
             target: kicker

diff --git a/applets/kicker/main.qml b/applets/kicker/main.qml
index 5c71937b15..2c08bc595c 100644
--- a/applets/kicker/main.qml
+++ b/applets/kicker/main.qml
@@ -77,7 +77,7 @@ PlasmoidItem {
             systemFavorites: kicker.systemFavorites
             rootModel: rootModelInstance
             runnerModel: runnerModelInstance
-            onInteractionConcluded: toggle()
+            onInteractionConcluded: hideAnimated()
         }
     }

-- 
